import 'package:flutter/material.dart'; class TimerScreen extends StatefulWidget { const TimerScreen({super.key}); @override State<TimerScreen> createState()=>_TimerScreenState(); } class _TimerScreenState extends State<TimerScreen>{ Duration d=Duration.zero; bool run=false; @override Widget build(BuildContext context){ return Scaffold(appBar: AppBar(title: Text('Service Timer')), body: Center(child: Column(mainAxisAlignment: MainAxisAlignment.center, children:[ Text('\${d.inHours}:\${d.inMinutes%60}:\${d.inSeconds%60}', style: TextStyle(fontSize:48)), ElevatedButton(onPressed:(){}, child: Text(run?'Pause':'Start')) ]))); } }
